css:
/* Keep SZARA's updated hero readable on desktop and mobile. */
.studio-hero .szara-headline{font-size:clamp(48px,5.1vw,80px);line-height:1.05;letter-spacing:-.06em;margin-right:0;max-width:100%}
.studio-hero .szara-headline em{letter-spacing:-.055em}
@media(max-width:720px){.studio-hero .szara-headline{font-size:clamp(37px,9.2vw,49px);line-height:1.09;letter-spacing:-.06em}}

@media(max-width:720px){
 header{position:relative!important;z-index:1000!important;overflow:visible!important}
 .mobile-menu,.mobile-menu[open]{position:relative!important;z-index:1001!important;background:#faf9f6!important;color:#211f20!important;isolation:auto!important}
 .mobile-menu>summary,.mobile-menu[open]>summary{background:#faf9f6!important;color:#211f20!important;border-bottom:0!important}
 .mobile-menu[open] .menu-bars i{background:#211f20!important}
 .mobile-menu[open] .menu-label-accent{color:#8b6268!important}
 .mobile-menu .mobile-menu-links{display:none!important}
 .mobile-menu[open] .mobile-menu-links{position:absolute!important;display:flex!important;flex-direction:column!important;top:100%!important;left:0!important;right:0!important;z-index:1002!important;gap:10px!important;padding:14px 18px 20px!important;margin:0!important;max-height:calc(100dvh - 155px)!important;overflow-y:auto!important;background:rgba(250,249,246,.24)!important;box-shadow:none!important;border:0!important;backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px)}
 .mobile-menu[open] .mobile-menu-links>a:not(.mobile-menu-contact){display:flex!important;align-items:center!important;justify-content:flex-start!important;min-height:64px!important;margin:0!important;padding:15px 20px!important;border:1px solid rgba(255,255,255,.78)!important;border-radius:12px!important;background:rgba(250,249,246,.83)!important;color:#211f20!important;font:400 clamp(23px,6vw,29px)/1.2 Georgia,serif!important;box-shadow:0 7px 20px rgba(25,24,25,.10)!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
 .mobile-menu .mobile-menu-links>a::after,.mobile-menu .mobile-menu-links>a::before{content:none!important;display:none!important}
 .mobile-menu[open] .mobile-menu-links>.mobile-menu-contact{display:flex!important;flex-direction:row!important;justify-content:space-between!important;align-items:center!important;min-height:54px!important;margin:0!important;padding:13px 18px!important;border:1px solid rgba(255,255,255,.65)!important;border-radius:12px!important;background:rgba(33,31,32,.88)!important;color:#f7f2f1!important;font-size:12px!important;box-shadow:0 8px 20px #0002!important}
 .mobile-menu[open] .mobile-menu-links>.mobile-menu-contact b{font-size:16px!important;color:#fff!important}
 .mobile-menu .mobile-menu-links>a:focus-visible{outline:3px solid #8b6268!important;outline-offset:2px!important}
}
@media(max-width:720px) and (prefers-reduced-motion:no-preference){
 .mobile-menu[open] .mobile-menu-links>a{animation:sz-glass-tile .32s ease both}
 .mobile-menu[open] .mobile-menu-links>a:nth-of-type(2){animation-delay:45ms}
 .mobile-menu[open] .mobile-menu-links>a:nth-of-type(3){animation-delay:90ms}
 .mobile-menu[open] .mobile-menu-links>a:nth-of-type(4){animation-delay:135ms}
}

@media(max-width:720px){
 .mobile-menu[open] .mobile-menu-links{gap:9px!important;padding:14px 16px 20px!important;background:rgba(40,40,45,.10)!important;backdrop-filter:blur(5px)!important;-webkit-backdrop-filter:blur(5px)!important}
 .mobile-menu[open] .mobile-menu-links>a:not(.mobile-menu-contact){min-height:63px!important;border-radius:19px!important;padding:15px 19px!important;background:rgba(35,35,40,.76)!important;border:1px solid rgba(255,255,255,.25)!important;box-shadow:0 8px 24px rgba(15,15,20,.15),inset 0 1px rgba(255,255,255,.18),inset 0 -1px rgba(0,0,0,.08)!important;backdrop-filter:blur(30px) saturate(150%)!important;-webkit-backdrop-filter:blur(30px) saturate(150%)!important;color:#fff!important;font-family:-apple-system,BlinkMacSystemFont,'SF Pro Display','Helvetica Neue',Arial,sans-serif!important;font-size:21px!important;font-weight:600!important;letter-spacing:-.035em!important}
 .mobile-menu[open] .mobile-menu-links>.mobile-menu-contact{min-height:59px!important;border-radius:19px!important;padding:14px 19px!important;background:rgba(35,35,40,.82)!important;border:1px solid rgba(255,255,255,.25)!important;box-shadow:0 8px 24px rgba(15,15,20,.15),inset 0 1px rgba(255,255,255,.16)!important;backdrop-filter:blur(30px) saturate(150%)!important;-webkit-backdrop-filter:blur(30px) saturate(150%)!important;font-family:-apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif!important}
 .mobile-menu[open] .mobile-menu-links>.mobile-menu-contact b{font-size:16px!important;font-weight:650!important}
 .mobile-menu[open] .mobile-menu-links>a::before,.mobile-menu[open] .mobile-menu-links>a::after{content:none!important;display:none!important}
}

@media(max-width:720px){
 .mobile-menu[open] .mobile-menu-links{gap:9px!important;padding:15px 20px 20px!important;background:rgba(31,31,34,.08)!important;backdrop-filter:blur(5px)!important;-webkit-backdrop-filter:blur(5px)!important}
 .mobile-menu[open] .mobile-menu-links>a:not(.mobile-menu-contact){min-height:58px!important;padding:13px 18px!important;border-radius:17px!important;background:rgba(28,28,32,.88)!important;border:1px solid rgba(255,255,255,.13)!important;box-shadow:0 7px 19px rgba(0,0,0,.14),inset 0 1px rgba(255,255,255,.10)!important;backdrop-filter:blur(24px) saturate(130%)!important;-webkit-backdrop-filter:blur(24px) saturate(130%)!important;color:#fff!important;font-size:19px!important;line-height:1.2!important}
 .mobile-menu[open] .mobile-menu-links>.mobile-menu-contact{min-height:57px!important;padding:13px 18px!important;border-radius:17px!important;background:rgba(42,37,41,.92)!important;border:1px solid rgba(230,199,203,.25)!important;justify-content:center!important}
 .mobile-menu[open] .mobile-menu-links>.mobile-menu-contact b{font-size:16px!important;white-space:normal!important;text-align:center!important}
 .mobile-menu[open] .mobile-menu-links>a::before,.mobile-menu[open] .mobile-menu-links>a::after{content:none!important;display:none!important}
}
@media(max-width:720px) and (prefers-reduced-motion:no-preference){
 .mobile-menu[open]:not(.is-closing) .mobile-menu-links{animation:none!important}
 .mobile-menu[open]:not(.is-closing) .mobile-menu-links>a{animation:sz-slide-in .42s cubic-bezier(.2,.85,.2,1) both!important}
 .mobile-menu[open]:not(.is-closing) .mobile-menu-links>a:nth-of-type(1){animation-delay:0ms!important}
 .mobile-menu[open]:not(.is-closing) .mobile-menu-links>a:nth-of-type(2){animation-delay:65ms!important}
 .mobile-menu[open]:not(.is-closing) .mobile-menu-links>a:nth-of-type(3){animation-delay:130ms!important}
 .mobile-menu[open]:not(.is-closing) .mobile-menu-links>a:nth-of-type(4){animation-delay:195ms!important}
 .mobile-menu[open]:not(.is-closing) .mobile-menu-links>a:nth-of-type(5){animation-delay:260ms!important}
 .mobile-menu[open]:not(.is-closing) .mobile-menu-links>a:nth-of-type(6){animation-delay:325ms!important}
 .mobile-menu.is-closing .mobile-menu-links{animation:none!important;pointer-events:none}
 .mobile-menu.is-closing .mobile-menu-links>a{animation:sz-slide-out .23s ease-in both!important}
 .mobile-menu.is-closing .mobile-menu-links>a:nth-of-type(6){animation-delay:0ms!important}
 .mobile-menu.is-closing .mobile-menu-links>a:nth-of-type(5){animation-delay:45ms!important}
 .mobile-menu.is-closing .mobile-menu-links>a:nth-of-type(4){animation-delay:90ms!important}
 .mobile-menu.is-closing .mobile-menu-links>a:nth-of-type(3){animation-delay:135ms!important}
 .mobile-menu.is-closing .mobile-menu-links>a:nth-of-type(2){animation-delay:180ms!important}
 .mobile-menu.is-closing .mobile-menu-links>a:nth-of-type(1){animation-delay:225ms!important}
}
@keyframes sz-slide-in{from{opacity:0;transform:translateX(34px)}to{opacity:1;transform:translateX(0)}}
@keyframes sz-slide-out{from{opacity:1;transform:translateX(0)}to{opacity:0;transform:translateX(34px)}}
